PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate WHERE {
  VALUES ?film { dbr:Le_Paria dbr:Young_Doctors_in_Love }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(lang(?directorLabel) = 'en') }
}
ORDER BY ?film ?directorLabel

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?director ?p ?o WHERE {
  VALUES ?film { dbr:Le_Paria dbr:Young_Doctors_in_Love }
  ?film dbo:director ?director .
  ?director ?p ?o .
  FILTER(
    ?p IN (dbo:birthDate, dbp:birthDate, dbp:birth_date, dbp:born, dbp:dateOfBirth, dbp:birth)
  )
}
ORDER BY ?film ?p

PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?birthDate ?abs ?birthDateComputed WHERE {
  VALUES ?film { dbr:Le_Paria dbr:Young_Doctors_in_Love }
  ?film dbo:director ?director .
  OPTIONAL { ?director dbo:birthDate ?birthDate }
  OPTIONAL { ?director dbo:abstract ?abs }
  BIND(
    IF(bound(?birthDate),
       ?birthDate,
       xsd:date(concat(REPLACE(str(?abs), '.*?(\\d{4}).*', '$1'), '-01-01'))
    ) AS ?birthDateComputed
  )
  OPTIONAL { ?film rdfs:label ?filmLabel FILTER(lang(?filmLabel) = 'en') }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER(lang(?directorLabel) = 'en') }
}
ORDER BY DESC(?birthDateComputed)
LIMIT 1

